def same_order(l1, l2):
    """Write a function to check if the common elements between two given lists are in the same order or not."""
    try:
        common = set(l1) & set(l2)
    except TypeError:
        # Elements are unhashable (e.g. lists); fall back to equality checks.
        common_in_l1 = [item for item in l1 if item in l2]
        common_in_l2 = [item for item in l2 if item in l1]
    else:
        common_in_l1 = [item for item in l1 if item in common]
        common_in_l2 = [item for item in l2 if item in common]
    return common_in_l1 == common_in_l2
